package com.tutorhub.review.service;
import com.tutorhub.common.exception.*;import com.tutorhub.common.security.UserPrincipal;import com.tutorhub.review.dto.ReviewRequest;import com.tutorhub.user.entity.Role;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReviewService {private final JdbcTemplate jdbc;public ReviewService(JdbcTemplate j){jdbc=j;}@Transactional public void create(UserPrincipal p,Long bookingId,ReviewRequest r){if(p.role()!=Role.PARENT)throw new ForbiddenException("Parent role required");var row=jdbc.query("select tutor_id from bookings where id=? and parent_id=? and status='COMPLETED'",rs->rs.next()?rs.getLong(1):null,bookingId,p.id());if(row==null)throw new NotFoundException("Completed booking not found");try{jdbc.update("insert into reviews(booking_id,parent_id,tutor_id,rating,comment) values(?,?,?,?,?)",bookingId,p.id(),row,r.rating(),r.comment());jdbc.update("update tutor_profiles set rating_avg=(select coalesce(avg(rating),0) from reviews where tutor_id=? and visible),rating_count=(select count(*) from reviews where tutor_id=? and visible) where user_id=?",row,row,row);}catch(DataIntegrityViolationException e){throw new ConflictException("REVIEW_EXISTS","Booking already has a review");}}@Transactional public void reply(UserPrincipal p,Long reviewId,String reply){if(p.role()!=Role.TUTOR)throw new ForbiddenException("Tutor role required");if(jdbc.update("update reviews set reply=?,replied_at=now() where id=? and tutor_id=?",reply,reviewId,p.id())==0)throw new NotFoundException("Review not found");}}
